# A 404 Unmatched does not mean the person is absent. Criteria that fall
# short of the minimum combination are never matched at all, and the answer
# is indistinguishable from a genuine no-match.

# Put a person in the database, carrying every identifier the match can ask
# for.

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "firstName": "Harriet",
    "lastName": "Kowalski",
    "dateOfBirth": "1975-03-14",
    "emails": [
      {
        "email": "harriet.kowalski@example.com"
      }
    ],
    "phones": [
      {
        "phoneNumber": "9075554242"
      }
    ],
    "addresses": [
      {
        "addressLine1": "742 Evergreen Terrace",
        "city": "Springfield",
        "stateOrProvince": "AK",
        "zipOrPostalCode": "99501"
      }
    ]
  }'
# → 201  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001,
#   "status": "Stored"
# }

# Now look for them by name alone. The person is unambiguously there — we
# just created them — but name alone is below the minimum combination, so no
# match is attempted at all.

curl -sS -X POST 'https://api.securevan.com/v4/people/find' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "firstName": "Harriet",
    "lastName": "Kowalski"
  }'
# → 404
# {
#   "vanId": null,
#   "status": "Unmatched"
# }

# When the body carries a vanId, the rest of the criteria are not used to
# search — they are not even checked for agreement. A name that belongs to
# nobody still matches, so a caller who sends a stale vanId alongside fresh
# details gets the stale record back.

# One person to aim at.

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "firstName": "Harriet",
    "lastName": "Kowalski",
    "dateOfBirth": "1975-03-14",
    "emails": [
      {
        "email": "harriet.kowalski@example.com"
      }
    ],
    "phones": [
      {
        "phoneNumber": "9075554242"
      }
    ],
    "addresses": [
      {
        "addressLine1": "742 Evergreen Terrace",
        "city": "Springfield",
        "stateOrProvince": "AK",
        "zipOrPostalCode": "99501"
      }
    ]
  }'
# → 201  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001,
#   "status": "Stored"
# }

# Ask for that vanId while giving a name that matches no record at all. The
# contradiction is ignored: the vanId decides the answer by itself.

curl -sS -X POST 'https://api.securevan.com/v4/people/find' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "vanId": 100000001,
    "firstName": "Desmond",
    "lastName": "Pemberton"
  }'
# → 302  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001,
#   "status": "Matched"
# }

# The endpoint does not attempt a match until the criteria reach one of a
