# When several records match, exactly one vanId comes back and nothing in
# the response says the match was ambiguous. Criteria including a name
# resolve to the oldest record.

CREATE_BODY='{
  "firstName": "Harriet",
  "lastName": "Kowalski",
  "dateOfBirth": "1975-03-14",
  "emails": [
    {
      "email": "harriet.kowalski@example.com"
    }
  ],
  "phones": [
    {
      "phoneNumber": "9075554242"
    }
  ],
  "addresses": [
    {
      "addressLine1": "742 Evergreen Terrace",
      "city": "Springfield",
      "stateOrProvince": "AK",
      "zipOrPostalCode": "99501"
    }
  ]
}'

# Create three records that are identical in every field.

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d "$CREATE_BODY"
# → 201  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001,
#   "status": "Stored"
# }

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d "$CREATE_BODY"
# → 201  Location: https://api.securevan.com/v4/people/100000002
# {
#   "vanId": 100000002,
#   "status": "Stored"
# }

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d "$CREATE_BODY"
# → 201  Location: https://api.securevan.com/v4/people/100000003
# {
#   "vanId": 100000003,
#   "status": "Stored"
# }

# All three match these criteria equally well. Exactly one vanId comes back,
# with nothing to say the other two exist — and it is the first one created.

curl -sS -X POST 'https://api.securevan.com/v4/people/find' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "firstName": "Harriet",
    "lastName": "Kowalski",
    "emails": [
      {
        "email": "harriet.kowalski@example.com"
      }
    ]
  }'
# → 302  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001,
#   "status": "Matched"
# }

# Both records must be the same kind of contact. The refusal names both
# vanIds and tells the caller to change the contactMode in the UI first, so
# it is the only 400 here that identifies which records were at fault.

# One person and one organization — the same database, two kinds of contact.

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "contactMode": "Organization",
    "lastName": "Harborview Tenants Union"
  }'
# → 201  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001,
#   "status": "Stored"
# }

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "firstName": "Theo",
    "lastName": "Marsh"
  }'
# → 201  Location: https://api.securevan.com/v4/people/100000002
# {
#   "vanId": 100000002,
#   "status": "Stored"
# }

# Simulate the merge, so the refusal is the only thing this behavior can
# possibly do. The kinds are checked before anything else about the pair.

curl -sS -X PUT 'https://api.securevan.com/v4/people/100000002/mergeInto?whatIf=true' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "vanId": 100000001
  }'
# → 400
# {
#   "errors": [
#     {
#       "code": "INVALID_PARAMETER",
#       "text": "VANID 100000002 and VANID 100000001 cannot be be merged as they are not the same type of Contact. In order to merge contacts, both records must either be people or organizations. To enable the merge, navigate to the incorrectly typed record and change its type."
#     }
#   ]
# }

# Only the exact value `true` simulates. Every other non-empty value —
# including `1` and `yes` — is read as false and performs the merge for
# real, and the response is identical either way, so nothing in it reveals
# which one happened.

# Two records to merge: the primary survives, the secondary is consumed.

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "firstName": "Rosa",
    "lastName": "Delgado",
    "emails": [
      {
        "email": "rosa.delgado@example.com"
      }
    ]
  }'
# → 201  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001,
#   "status": "Stored"
# }

curl -sS -X POST 'https://api.securevan.com/v4/people/create' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "firstName": "Rosa",
    "lastName": "Delgado",
    "emails": [
      {
        "email": "rdelgado@example.com"
      }
    ]
  }'
# → 201  Location: https://api.securevan.com/v4/people/100000002
# {
#   "vanId": 100000002,
#   "status": "Stored"
# }

# Ask for a simulation with whatIf=yes — truthy in every language a caller
# might write this in. The 200 below is exactly what a real simulation
# returns.

curl -sS -X PUT 'https://api.securevan.com/v4/people/100000002/mergeInto?whatIf=yes' \
  -u "app-name:$NGP_API_KEY|1" \
  -H 'Content-Type: application/json' \
  -d '{
    "vanId": 100000001
  }'
# → 200  Location: https://api.securevan.com/v4/people/100000001
# {
#   "vanId": 100000001
# }

# But nothing was simulated. The secondary is gone for good — only the
# literal string `true` suppresses the write.

curl -sS -X GET 'https://api.securevan.com/v4/people/100000002' \
  -u "app-name:$NGP_API_KEY|1"
# → 404
# {
#   "errors": [
#     {
#       "code": "NOT_FOUND",
